    "La flamme se rallume": "炎が再び灯る",
    "👻 Une vie gardée": "👻 命を1つ確保",
    "🔥 La flamme d'Hestia te sauve !": "🔥 ヘスティアの炎があなたを救った！",
    "👻 Hermès te ramène des Enfers !": "👻 ヘルメスが冥界から連れ戻した！",
    "Gorgone : chaque coup d'Athéna a {petrify:%}% de chance de changer l'ennemi en pierre pendant {@STONE_TIME} s (pas les super ennemis). La pierre est un mur : les ennemis qui la touchent s'arrêtent": "ゴルゴン：アテナの攻撃は{petrify:%}%の確率で敵を{@STONE_TIME}秒間石に変える（スーパー敵には効かない）。石は壁になり、触れた敵は止まる",
