    "🎯 Défi du jour": "🎯 デイリーチャレンジ",
    "▶ C'est parti !": "▶ スタート！",
    "🏠 Retour à ma partie": "🏠 自分のゲームに戻る",
    "📅 Défis et collection": "📅 チャレンジとコレクション",
    "Quitter le défi": "チャレンジをやめる",
    "Facile": "かんたん",
    "Moyenne": "ふつう",
    "Difficile": "むずかしい",
    "Soleil (de base)": "太陽（基本）",
    "Argent lunaire": "月の銀",
    "Émeraude": "エメラルド",
    "Cramoisi": "クリムゾン",
